INSERT INTO monthly_saving_missions (
    user_id, monthly_spending_analysis_id, mission_category_selection_id, category_id,
    target_year_month, reduction_rate, baseline_spending_amount,
    monthly_reduction_target, monthly_usage_target, planned_saving_amount, start_week, status
) VALUES (
    #{userId}, #{monthlySpendingAnalysisId}, #{missionCategorySelectionId}, #{categoryId},
    #{targetYearMonth}, #{reductionRate}, #{baselineSpendingAmount},
    #{monthlyReductionTarget}, #{monthlyUsageTarget}, #{plannedSavingAmount}, #{startWeek}, #{status}
)

INSERT INTO weekly_saving_missions (
    monthly_saving_mission_id, week_number, period_start_date, period_end_date,
    weekly_usage_limit, weekly_expected_saving, status
) VALUES (
    #{monthlySavingMissionId}, #{weekNumber}, #{periodStartDate}, #{periodEndDate},
    #{weeklyUsageLimit}, #{weeklyExpectedSaving}, #{status}
)
